def check_openai_key():
    """[필수] Streamlit Secrets 또는 실행 환경의 API 키를 사용합니다."""
    if os.environ.get("OPENAI_API_KEY"):
        return True
    try:
        key = st.secrets.get("OPENAI_API_KEY", "")
    except Exception:
        key = ""
    if key:
        os.environ["OPENAI_API_KEY"] = str(key)
    return bool(key)


